class WholeRowConditionFrameTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final String HIDDEN = "absentFromAllAlgebraVars";
	private static final String COUNT = "count";

	@ParameterizedTest
	@MethodSource("cases")
	void realExistsAndNotExistsObserveWholeMappingIdentity(Shape shape, boolean experimental) {
		DefaultEvaluationStrategy strategy = strategy(experimental);
		var exists = strategy.precompile(new Exists(shape.body()), context());
		var notExists = strategy.precompile(new Not(new Exists(shape.body())), context());
		assertThat(strategy.isTrue(exists, EmptyBindingSet.getInstance())).isEqualTo(shape.withEmpty);
		assertThat(strategy.isTrue(exists, input())).isEqualTo(!shape.withEmpty);
		assertThat(strategy.isTrue(notExists, EmptyBindingSet.getInstance())).isEqualTo(!shape.withEmpty);
		assertThat(strategy.isTrue(notExists, input())).isEqualTo(shape.withEmpty);
	}

	@ParameterizedTest
	@MethodSource("cases")
	void retainedFrameMustNotBeElidedForAWholeRowIdentityCondition(Shape shape, boolean experimental) {
		Filter retained = new Filter(new SingletonSet(), new Not(new Not(new Exists(shape.body()))));
		// Count is a local body output; allowing that finite name cannot expose arbitrary incoming row columns.
		retained.setConditionBindingScope(ConditionBindingScope.retain(
				shape == Shape.COUNT_DISTINCT_STAR ? Set.of(COUNT) : Set.of()));
		Filter all = retained.clone();
		all.setConditionBindingScope(ConditionBindingScope.ALL);
		List<BindingSet> original = List.of(new QueryBindingSet(input()));
		assertThat(rows(retained, input(), experimental))
				.containsExactlyElementsOf(shape.withEmpty ? original : List.of());
		assertThat(rows(all, input(), experimental)).containsExactlyElementsOf(shape.withEmpty ? List.of() : original);
		assertThat(FilterBindingScope.allowsAllConditionBindings(retained))
				.as("the exact current condition observes arbitrary mapping names outside the finite retained frame")
				.isFalse();
	}

	@Test
	void unvaluedConstantFlagStillUsesRealScalarVarAndBoundInputLookup() {
		DefaultEvaluationStrategy strategy = strategy(false);
		Var input = Var.of(HIDDEN, null, false, true);
		assertThat(strategy.precompile(input, context()).evaluate(input())).isEqualTo(VF.createLiteral(1));
		assertThat(strategy.isTrue(strategy.precompile(new Bound(input.clone()), context()), input())).isTrue();
		assertThat(strategy.isTrue(strategy.precompile(new Bound(input.clone()), context()),
				EmptyBindingSet.getInstance()))
						.isFalse();
		Var constant = Var.of(HIDDEN, VF.createLiteral(2), false, true);
		assertThat(strategy.precompile(constant, context()).evaluate(input())).isEqualTo(VF.createLiteral(2));
		assertThat(strategy.isTrue(strategy.precompile(new Bound(constant.clone()), context()),
				EmptyBindingSet.getInstance()))
						.isTrue();
	}

	private static Stream<Arguments> cases() {
		return Stream.of(Shape.values())
				.flatMap(shape -> Stream.of(Arguments.of(shape, false), Arguments.of(shape, true)));
	}

	private enum Shape {
		INTERSECTION(true),
		DISTINCT_OFFSET(false),
		REDUCED_OFFSET(false),
		COUNT_DISTINCT_STAR(false);

		final boolean withEmpty;

		Shape(boolean withEmpty) {
			this.withEmpty = withEmpty;
		}

		TupleExpr body() {
			if (this == INTERSECTION) {
				return new Intersection(new SingletonSet(), emptyProjection());
			}
			Union rows = new Union(new SingletonSet(), emptyProjection());
			if (this == DISTINCT_OFFSET) {
				return new Slice(new Distinct(rows), 1, 1);
			}
			if (this == REDUCED_OFFSET) {
				return new Slice(new Reduced(rows), 1, 1);
			}
			Group count = new Group(rows, Set.of(), List.of(new GroupElem(COUNT, new Count(null, true))));
			Filter two = new Filter(count,
					new Compare(Var.of(COUNT), new ValueConstant(VF.createLiteral(2)), Compare.CompareOp.EQ));
			two.setConditionBindingScope(ConditionBindingScope.ALL);
			return two;
		}
	}

	private static Projection emptyProjection() {
		return new Projection(new SingletonSet(), new ProjectionElemList(), false);
	}

	private static QueryEvaluationContext context() {
		return new QueryEvaluationContext.Minimal(null);
	}

	private static QueryBindingSet input() {
		QueryBindingSet input = new QueryBindingSet();
		input.addBinding(HIDDEN, VF.createLiteral(1));
		return input;
	}

	private static DefaultEvaluationStrategy strategy(boolean experimental) {
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		strategy.setQueryExecutionPolicy(QueryExecutionPolicy.of(experimental));
		return strategy;
	}

	private static List<BindingSet> rows(TupleExpr expression, BindingSet input, boolean experimental) {
		List<BindingSet> result = new ArrayList<>();
		try (var rows = strategy(experimental).precompile(expression, context()).evaluate(input)) {
			while (rows.hasNext()) {
				result.add(new QueryBindingSet(rows.next()));
			}
		}
		return result;
	}
}
